world node {
    use aap:caps/types@0.1.0.{published-digest, run-report};

    import aap:caps/state-rw@0.1.0;

    export run: func(published: published-digest) -> run-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Authority is exactly StateHandle<'seen', read-write>: get/put/delete.
        // Mark every considered id as seen, keyed by id, valued by the run date.
        // `recorded` counts ids newly written this run; it is a u32, so the
        // `recorded >= 0` postcondition holds for every output by construction.
        let mut recorded: u32 = 0;

        for id in &published.considered {
            if state_rw::get(id).is_none() {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

